import Banner from '@chronos-ui/core/react/Banner';
import '@chronos-ui/core/theme.css';

<Banner
  title="Summer Collection 2026"
  subtitle="Discover the new season"
  ctaText="Shop Now"
  textAlignment="center"
  media={{ type: 'image', url: '/hero.jpg' }}
  mapLinks={[{ url: '/shop' }]}
/>

import AnnouncementBar from '@chronos-ui/core/react/AnnouncementBar';
import '@chronos-ui/core/theme.css';

<AnnouncementBar
  message="🚀 Free shipping on orders over $75 — Shop the sale"
  backgroundColor="#7c3aed"
  textColor="#ffffff"
  mapLinks={[{ url: '/sale' }]}
/>

import GridBanner from '@chronos-ui/core/react/GridBanner';
import '@chronos-ui/core/theme.css';

const items = [
  { id: '1', title: "Women's", media: { type: 'image', url: '/women.jpg' }, mapLinks: [{ url: '/women' }] },
  { id: '2', title: "Men's",   media: { type: 'image', url: '/men.jpg' },   mapLinks: [{ url: '/men' }] },
  { id: '3', title: 'Footwear', media: { type: 'image', url: '/shoes.jpg' }, mapLinks: [{ url: '/shoes' }] },
];

<GridBanner items={items} columns={3} />

import MediaGrid from '@chronos-ui/core/react/MediaGrid';
import '@chronos-ui/core/theme.css';

<MediaGrid
  primaryMedia={{
    id: 'p1',
    media: { type: 'image', url: '/primary.jpg' },
    mapLinks: [{ url: '/feature' }],
    altText: 'Feature story',
  }}
  secondaryMedia={[
    { id: 's1', media: { type: 'image', url: '/sec1.jpg' }, mapLinks: [{ url: '/story-1' }] },
    { id: 's2', media: { type: 'image', url: '/sec2.jpg' }, mapLinks: [{ url: '/story-2' }] },
  ]}
/>

import RowScrollable from '@chronos-ui/core/react/RowScrollable';
import '@chronos-ui/core/theme.css';

const items = [
  { id: '1', title: 'Linen Dress',  subtitle: '$89.00', media: { type: 'image', url: '/p1.jpg' }, mapLinks: [{ url: '/p/1' }] },
  { id: '2', title: 'Oxford Shirt', subtitle: '$55.00', media: { type: 'image', url: '/p2.jpg' }, mapLinks: [{ url: '/p/2' }] },
];

<RowScrollable title="Featured Products" items={items} />

import SlidingBanner from '@chronos-ui/core/react/SlidingBanner';
import '@chronos-ui/core/theme.css';

const items = [
  { id: '1', title: 'Summer Sale',   subtitle: 'Up to 50% off', ctaText: 'Shop Now', media: { type: 'image', url: '/s1.jpg' }, mapLinks: [{ url: '/sale' }] },
  { id: '2', title: 'New Arrivals', subtitle: 'Latest collection', ctaText: 'Explore', media: { type: 'image', url: '/s2.jpg' }, mapLinks: [{ url: '/new' }] },
];

<SlidingBanner
  items={items}
  config={{
    autoStart: true,
    rotateAgain: true,
    delayMs: 5000,
    showNextPrev: true,
    showDots: true,
    animationEffect: 'fade',
    backgroundEffect: 'particles',
  }}
/>

import AlternatingSlider from '@chronos-ui/core/react/AlternatingSlider';
import '@chronos-ui/core/theme.css';

const items = [
  { id: 'a', title: 'Women',    subtitle: 'New season', ctaText: 'Shop', media: { type: 'image', url: '/w.jpg' } },
  { id: 'b', title: 'Men',      subtitle: 'Essentials', ctaText: 'Shop', media: { type: 'image', url: '/m.jpg' } },
  { id: 'c', title: 'Kids',     subtitle: 'Play more',  ctaText: 'Shop', media: { type: 'image', url: '/k1.jpg' } },
  { id: 'd', title: 'Footwear', subtitle: 'Step up',    ctaText: 'Shop', media: { type: 'image', url: '/k2.jpg' } },
];

<AlternatingSlider
  items={items}
  config={{ columns: 2, autoStart: true, delayMs: 4000, showArrows: true, showDots: true }}
/>

import TimerWidget from '@chronos-ui/core/react/TimerWidget';
import '@chronos-ui/core/theme.css';

<TimerWidget
  title="Sale ends in:"
  targetDate="2026-12-31T23:59:59Z"
/>

import WysiwygRenderer from '@chronos-ui/core/react/WysiwygRenderer';
import '@chronos-ui/core/theme.css';

// html comes from your CMS API response
const html = `<h2>Autumn Collection</h2><p>...</p>`;

<WysiwygRenderer content={html} />

import RichTextEditor from '@chronos-ui/core/react/RichTextEditor';
import '@chronos-ui/core/theme.css';

<RichTextEditor 
  content="<p>Hello World!</p>"
  availableClasses={['text-pink-500', 'font-bold']}
  onChange={(html) => console.log(html)}
/>
